function FooterCol({ title, links }: { title: string; links: string[][] }) {
  return <div><p className="eyebrow mb-5 text-[#c7f000]">{title}</p><div className="grid gap-3">{links.map(([label, href]) => <Link key={label} href={href} className="w-fit text-sm text-[#d3d9dc] transition-colors hover:text-[#c7f000]" data-testid={`link-footer-${label.toLowerCase().replaceAll(' ', '-')}`}>{label}</Link>)}</div></div>;
}

function Button({ children, href, variant = 'dark', onClick, testId }: { children: ReactNode; href?: string; variant?: 'dark' | 'lime' | 'outline'; onClick?: () => void; testId?: string }) {
  const style = variant === 'lime' ? 'bg-[#c7f000] text-[#071a33]' : variant === 'outline' ? 'border border-[#071a33]/20 text-[#071a33] hover:bg-[#071a33] hover:text-[#f7f6f1]' : 'bg-[#071a33] text-[#f7f6f1]';
  const cls = `inline-flex min-h-12 items-center justify-center gap-2 rounded-full px-5 text-sm font-bold transition-all hover:-translate-y-0.5 ${style}`;
  return href ? <Link href={href} className={cls} data-testid={testId}>{children}</Link> : <button onClick={onClick} className={cls} data-testid={testId}>{children}</button>;
}

function SectionHeading({ eyebrow, title, body, action }: { eyebrow: string; title: string; body?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow mb-3 text-[#6f7e00]">{eyebrow}</p><h2 className="font-display text-3xl font-bold leading-[1.05] tracking-[-.05em] text-[#071a33] sm:text-5xl">{title}</h2>{body && <p className="mt-4 max-w-[520px] text-sm leading-6 text-[#697177]">{body}</p>}</div>{action}</div>;
}

function Rating({ value }: { value: number }) {
  return <span className="inline-flex items-center gap-1 text-sm font-semibold"><Star size={14} fill="currentColor" className="text-[#a5c900]" /> {value.toFixed(1)}</span>;
}

function CourseCard({ course, compact = false }: { course: Course; compact?: boolean }) {
  const [fav, setFav] = useState(false);
  return <article className={`group overflow-hidden rounded-2xl border border-[#071a33]/12 bg-[#fffefa] ${compact ? '' : 'min-w-0'}`} data-testid={`card-course-${course.id}`}>
    <div className="relative aspect-[1.52] overflow-hidden bg-[#dfe3e4]">
      <img src={course.image} alt={`${course.title} course`} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" />
      <span className={`absolute left-3 top-3 rounded-full px-3 py-1 text-[10px] font-bold tracking-[.1em] ${course.accent === 'lime' ? 'bg-[#c7f000] text-[#071a33]' : 'bg-[#071a33] text-[#f7f6f1]'}`}>{course.badge}</span>
      <button onClick={() => setFav(!fav)} aria-label={fav ? 'Remove from favourites' : 'Add to favourites'} className="absolute right-3 top-3 grid h-9 w-9 place-items-center rounded-full bg-[#f7f6f1]/90 text-[#071a33] transition-transform hover:scale-105" data-testid={`button-favorite-${course.id}`}><Heart size={16} fill={fav ? 'currentColor' : 'none'} className={fav ? 'text-[#b3d800]' : ''} /></button>
      <span className="absolute bottom-3 left-3 grid h-9 w-9 place-items-center rounded-full border border-[#f7f6f1]/70 bg-[#071a33]/60 text-[#f7f6f1]"><Play size={14} fill="currentColor" /></span>
    </div>
    <div className="p-4 sm:p-5">
      <p className="eyebrow text-[#78828a]">{course.category} <span className="mx-1 text-[#b5babd]">/</span> {course.level}</p>
      <Link href={`/courses/${course.id}`} className="mt-3 block font-display text-lg font-bold leading-tight tracking-[-.04em] text-[#071a33] hover:underline" data-testid={`link-course-${course.id}`}>{course.title}</Link>
      <p className="mt-2 text-xs text-[#6e757b]">{course.instructor}</p>
      <div className="mt-4 flex items-center justify-between text-xs text-[#687179]"><span><Rating value={course.rating} /> <span className="ml-1 text-[#7d858b]">({course.learners})</span></span><span className="inline-flex items-center gap-1"><Clock3 size={13} /> {course.duration}</span></div>
      <div className="mt-5 flex items-end justify-between border-t border-[#071a33]/10 pt-4"><div><span className="font-display text-xl font-bold">₹{course.price.toLocaleString('en-IN')}</span><del className="ml-2 text-xs text-[#8b9094]">₹{course.originalPrice.toLocaleString('en-IN')}</del></div><Link href={`/courses/${course.id}`} className="grid h-9 w-9 place-items-center rounded-full bg-[#071a33] text-[#f7f6f1] transition-transform hover:translate-x-1" aria-label={`View ${course.title}`} data-testid={`button-view-course-${course.id}`}><ArrowRight size={15} /></Link></div>
    </div>
  </article>;
}

